}

impl ObjectSevSnpGuest {
    fn new(is_snp: bool, cbitpos: u32, reduced_phys_bits: u32, host_data: Option<String>) -> Self {
        ObjectSevSnpGuest {
            id: (if is_snp { "snp" } else { "sev" }).to_owned(),
            cbitpos,
            reduced_phys_bits,
            kernel_hashes: true,
            host_data,
            policy: 0x30000,
            is_snp,
        }
    }

