        config.security_info.seccomp_sandbox = seccomp_sandbox.map(str::to_owned);
        let params = build_test_cmdline("seccomp-sandbox", &config).await;

        let values: Vec<&str> = params
            .windows(2)
            .filter_map(|args| (args[0] == "-sandbox").then_some(args[1].as_str()))
            .collect();

        assert_eq!(values, expected_values);
    }

    #[rstest]
    #[case::default_is_host("", false, "host")]
    #[case::from_config_without_protection("EPYC-Genoa", false, "EPYC-Genoa")]
    #[case::sev_snp_from_config("EPYC-Milan", true, "EPYC-Milan")]
    #[actix_rt::test]
    #[serial]
    async fn test_cpu_model(
        #[case] cpu_model: &str,
        #[case] sev_snp: bool,
        #[case] expected_model: &str,
    ) {
        let mut config = test_qemu_config(Some("none"), false);
        config.cpu_info.cpu_model = cpu_model.to_owned();
        let _ = std::fs::remove_file(QMP_SOCKET_FILE);
        let mut cmdline = QemuCmdLine::new("cpu-model", &config).unwrap();
        if sev_snp {
            cmdline.add_sev_snp_protection_device(1, 1, "/usr/share/ovmf/OVMF.fd", &None);
        }
        let params = cmdline.build().await.unwrap();
        let _ = std::fs::remove_file(QMP_SOCKET_FILE);

        assert!(params
            .windows(2)
            .any(|args| args[0] == "-cpu" && args[1].split(',').next() == Some(expected_model)));
    }

    #[actix_rt::test]
    #[serial]
    async fn test_machine_kernel_irqchip() {
        let config = test_qemu_config(Some("none"), false);
        let params = build_test_cmdline("kernel-irqchip", &config).await;

        let machine_value = params
            .windows(2)
            .find_map(|args| (args[0] == "-machine").then_some(args[1].as_str()))
            .expect("-machine argument must be present");

        // ppc64le: kernel_irqchip=on must not be a part of the args
        // so the kernel can fall back to XICS when KVM_CAP_PPC_IRQ_XIVE is unavailable (e.g. on LPARs).
        // Every other arch must include it.
        #[cfg(all(target_arch = "powerpc64", target_endian = "little"))]
        assert!(
            !machine_value.contains("kernel_irqchip="),
            "kernel_irqchip must not be set on ppc64le, got: {}",
            machine_value
        );
        #[cfg(not(all(target_arch = "powerpc64", target_endian = "little")))]
        assert!(
            machine_value.contains("kernel_irqchip=on"),
            "kernel_irqchip=on must be present on this arch, got: {}",
            machine_value
        );
    }
}

